CREATE SET TABLE MDP01_META.META_COLUMN ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      column_id INTEGER NOT NULL,      table_id INTEGER NOT NULL,      column_name VARCHAR(128) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      column_position INTEGER NOT NULL,      datatype_id INTEGER NOT NULL,      column_type VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC,      column_length INTEGER,      decimal_total_digits INTEGER,      decimal_fractional_digits INTEGER,      nullable CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'Y',      default_value VARCHAR(2000) CHARACTER SET LATIN NOT CASESPECIFIC,      column_format VARCHAR(128) CHARACTER SET LATIN NOT CASESPECIFIC,      is_business_key CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'N',      is_technical_key CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'N',      is_audit_column CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'N',      is_scd_column CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'N',      scd_type VARCHAR(20) CHARACTER SET LATIN NOT CASESPECIFIC,      schutzniveau VARCHAR(10) CHARACTER SET LATIN NOT CASESPECIFIC,      is_pii CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'N',      masking_rule VARCHAR(100) CHARACTER SET LATIN NOT CASESPECIFIC,      comment_string VARCHAR(2000) CHARACTER SET LATIN NOT CASESPECIFIC,      business_name VARCHAR(128) CHARACTER SET LATIN NOT CASESPECIFIC,      business_definition VARCHAR(2000) CHARACTER SET LATIN NOT CASESPECIFIC,      beispielwert VARCHAR(200) CHARACTER SET LATIN NOT CASESPECIFIC,      ersterfassungsdatum TIMESTAMP(6) NOT NULL,      aenderungsdatum TIMESTAMP(6) NOT NULL,      is_pk CHAR(1) CHARACTER SET UNICODE NOT CASESPECIFIC DEFAULT 'N',      is_fk CHAR(1) CHARACTER SET UNICODE NOT CASESPECIFIC DEFAULT 'N',      is_pi CHAR(1) CHARACTER SET UNICODE NOT CASESPECIFIC DEFAULT 'N',      is_hash CHAR(1) CHARACTER SET UNICODE NOT CASESPECIFIC DEFAULT 'N',      charset VARCHAR(10) CHARACTER SET UNICODE NOT CASESPECIFIC,      is_casespecific CHAR(1) CHARACTER SET UNICODE NOT CASESPECIFIC DEFAULT 'N')PRIMARY INDEX ( column_id )UNIQUE INDEX ( table_id ,column_name );